// Writes the catalog's index.json from a directory of static JSON files.
//
// Usage: npm run catalog -- <catalog-dir> [--stdout]
//
// The directory is the one served by caddy (or any static host) under the URL
// the app fetches (`VITE_CATALOG_URL`, default `<app>/catalog/`):
//
//   catalog/
//     index.json            <- generated by this script
//     locations.json
//     dates.json
//     degrees/*.degree      flat: a subdirectory is an error, no index written
//     timetables/**/*.{json,timetable}  plain Subject[], subdirectories allowed
//
// Every entry carries an 8-character hash, so the app only re-downloads what
// really changed. A timetable's hash is `Subjects.hash()` of its validated
// subjects, so the app matches a timetable by hash without downloading it; its
// name is its file name, so the index carries no other metadata.
//
// jiti loads the primitives' TypeScript directly, so the hash is computed by
// the very code the app checks it with.
import { readdir, readFile, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import { parseArgs } from "node:util";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url);
const { shortHash, subjectsFileSchema, subjectsHash } = await jiti.import(
  "../src/lib/primitives/subject.ts",
);
const { degreeSchema } = await jiti.import("../src/lib/primitives/meta.ts");
const { DEGREE_EXTENSION, DEGREES_DIR } = await jiti.import("../src/lib/primitives/catalog.ts");
const { cleanName, nameFromFile, nameProblem, sameName } = await jiti.import(
  "../src/lib/primitives/name.ts",
);

const usage = "usage: npm run catalog -- <catalog-dir> [--stdout]\n";

let options;
try {
  options = parseArgs({
    allowPositionals: true,
    options: { stdout: { type: "boolean", default: false }, help: { type: "boolean", short: "h" } },
  });
} catch (error) {
  process.stderr.write(`${error.message}\n${usage}`);
  process.exit(1);
}
if (options.values.help) {
  process.stdout.write(usage);
  process.exit(0);
}
if (options.positionals.length !== 1) {
  process.stderr.write(usage);
  process.exit(1);
}
const toStdout = options.values.stdout;
const dir = options.positionals[0];

// Every file below `sub` ending in one of `extensions`, subdirectories
// included, as paths relative to the catalog root. Any other file is reported,
// so a file the index leaves out never goes unnoticed.
async function filesIn(sub, extensions) {
  let entries;
  try {
    entries = await readdir(path.join(dir, sub), { recursive: true, withFileTypes: true });
  } catch {
    // A missing subdirectory is normal: the catalog may serve only some kinds.
    return [];
  }
  const relative = (entry) =>
    path.relative(dir, path.join(entry.parentPath, entry.name)).split(path.sep).join("/");
  const files = [];
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (extensions.some((extension) => entry.name.endsWith(extension))) files.push(relative(entry));
    else process.stderr.write(`skipped ${relative(entry)}: not ${extensions.join(" or ")}\n`);
  }
  return files.sort();
}

async function read(relative) {
  const file = path.join(dir, relative);
  const raw = await readFile(file, "utf8");
  // The file's mtime: the picker dialog shows it as the "last changed" of a
  // catalog row, so a user can tell an old file from a fresh one.
  const modified = (await stat(file)).mtime.toISOString();
  return { json: JSON.parse(raw), modified };
}

// A timetable: `Subjects.hash()` of what the app will read from the file, so
// defaults filled in by the schema count the same as written-out ones.
function timetableHash(json) {
  const parsed = subjectsFileSchema.safeParse(json);
  if (!parsed.success) throw new Error("not a list of subjects");
  return subjectsHash(parsed.data);
}

const files = [];

// Why each `nameProblem` code keeps a name from being a file on every system.
const problems = {
  empty: "is empty",
  chars: 'contains one of < > : " / \\ | ? * or a control character',
  end: "ends with a dot or space",
  reserved: "is a reserved name on Windows",
  long: "is too long",
};

// A path the catalog serves must check out and download on Windows, Android
// and iOS too, and a timetable's file name becomes its name in the app, which
// then shows a cleaned one: a warning, not a refusal.
function checkPath(relative, kind) {
  for (const segment of relative.split("/")) {
    const problem = nameProblem(segment);
    if (problem) process.stderr.write(`warning: ${relative}: "${segment}" ${problems[problem]}\n`);
  }
  if (kind !== "timetables") return;
  const name = nameFromFile(relative);
  const shown = cleanName(name, "Timetable");
  if (shown !== name) {
    process.stderr.write(`warning: ${relative}: the app names this timetable "${shown}"\n`);
  }
}

// The parsed JSON of the file added, `undefined` when it was skipped.
async function add(relative, kind, hashOf = shortHash) {
  checkPath(relative, kind);
  try {
    const file = await read(relative);
    files.push({ path: relative, kind, hash: hashOf(file.json), modified: file.modified });
    return file.json;
  } catch (error) {
    process.stderr.write(`skipped ${relative}: ${error.message}\n`);
    return undefined;
  }
}

// `degreeProgram` (file name in `degrees/` without `.degree`) -> its subject
// codes (upper case, as the app compares them). Files are never merged: a
// timetable subject names its file, so a name it points at that is missing
// shows as a bare code in the app — worth a warning, not a refusal.
const programs = new Map();

function collectCodes(relative, json) {
  const parsed = degreeSchema.safeParse(json);
  if (!parsed.success) {
    process.stderr.write(`warning: ${relative} does not match the degree format\n`);
    return;
  }
  const codes = new Set(parsed.data.subjects.map(({ code }) => code.toUpperCase()));
  programs.set(relative.slice(DEGREES_DIR.length, -DEGREE_EXTENSION.length), codes);
}

// Like `subjectInfoOf`: the whole code, else the part in front of a slash.
function knows(codes, name) {
  const key = name.toUpperCase();
  if (codes.has(key)) return true;
  const cut = key.lastIndexOf("/");
  return cut > 0 && knows(codes, key.slice(0, cut));
}

function checkPrograms(relative, json) {
  const parsed = subjectsFileSchema.safeParse(json);
  if (!parsed.success) return;
  const warned = new Set();
  for (const { name, degreeProgram } of parsed.data) {
    if (!degreeProgram) continue;
    const codes = programs.get(degreeProgram);
    const problem = !codes
      ? `names degreeProgram ${degreeProgram}, which is no ${DEGREES_DIR}${degreeProgram}${DEGREE_EXTENSION}`
      : knows(codes, name)
        ? null
        : `subject ${name} is not in ${DEGREES_DIR}${degreeProgram}${DEGREE_EXTENSION}`;
    if (problem && !warned.has(problem)) {
      warned.add(problem);
      process.stderr.write(`warning: ${relative}: ${problem}\n`);
    }
  }
}

// `degrees/` is flat: a subject names its degree file by its bare name, so a
// file in a subdirectory could never be found. Refused before anything is
// written, unlike every other problem here.
async function checkDegreesFlat() {
  let entries;
  try {
    entries = await readdir(path.join(dir, "degrees"), { withFileTypes: true });
  } catch {
    return;
  }
  const nested = entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);
  if (nested.length === 0) return;
  for (const name of nested) {
    process.stderr.write(`error: ${DEGREES_DIR}${name}/: ${DEGREES_DIR} must not have subdirectories\n`);
  }
  process.stderr.write("index.json not written\n");
  process.exit(1);
}

await checkDegreesFlat();
await add("locations.json", "locations");
// One dates file, like one locations file: the app holds a single
// `SemesterDates` and installs this one by itself.
await add("dates.json", "dates");
for (const relative of await filesIn("degrees", [DEGREE_EXTENSION])) {
  const json = await add(relative, "degrees");
  if (json !== undefined) collectCodes(relative, json);
}
// `.timetable` is what the app downloads and uploads, so such a file can be
// dropped in as it is; the app names it after the file without the extension.
for (const relative of await filesIn("timetables", [".json", ".timetable"])) {
  const json = await add(relative, "timetables", timetableHash);
  if (json !== undefined) checkPrograms(relative, json);
}

// Windows, macOS and iOS see paths differing only in case (or Unicode form)
// as one file: one of them would be lost there.
files.forEach((file, i) => {
  const first = files.findIndex((other) => sameName(other.path, file.path));
  if (first !== i) {
    process.stderr.write(`warning: ${file.path} and ${files[first].path} differ only in case\n`);
  }
});

const index = { version: 1, generated: new Date().toISOString(), files };
const text = JSON.stringify(index, null, 2) + "\n";

if (toStdout) process.stdout.write(text);
else {
  await writeFile(path.join(dir, "index.json"), text);
  process.stderr.write(`wrote ${path.join(dir, "index.json")} (${files.length} files)\n`);
}
